INSERT INTO zgloszenia (id, data, podmiot_typ, podmiot, typ, powod, opis, autor, waga, klient_id) VALUES ('ZG-007', '2026-08-21', 'instytucja', 'Instytucja Szkoleniowa Beta', 'Instytucja', 'Próba zaniżenia prowizji', 'Instytucja obcięła prowizję do 5 tys. powołując się na rzekome życzenie klienta. Klient chciał, żeby inny trener realizował szkolenie, więc podjęli negocjacje z pominięciem nas.', 'Bartłomiej Olejnik', 'wysoka', NULL);
INSERT INTO zgloszenia (id, data, podmiot_typ, podmiot, typ, powod, opis, autor, waga, klient_id) VALUES ('ZG-006', '2026-07-14', 'instytucja', 'Instytucja Szkoleniowa Alfa', 'Instytucja', 'Spóźnione formularze', 'Trzeci raz w tym roku formularz od handlowca wpłynął w ostatnim dniu naboru. Klient miał pretensje do nas.', 'Łucja Wierzbicka', 'średnia', NULL);
INSERT INTO zgloszenia (id, data, podmiot_typ, podmiot, typ, powod, opis, autor, waga, klient_id) VALUES ('ZG-005', '2026-06-30', 'klient', 'Marbud sp. z o.o.', 'Klient', 'Podejrzenie wyłudzenia', 'Firma zgłosiła 11 uczestników, z czego 6 nie figuruje w ZUS jako zatrudnieni. Wniosek wstrzymany do wyjaśnienia.', 'Martyna Kowal', 'wysoka', NULL);
INSERT INTO zgloszenia (id, data, podmiot_typ, podmiot, typ, powod, opis, autor, waga, klient_id) VALUES ('ZG-004', '2026-05-19', 'instytucja', 'Instytucja Szkoleniowa Beta', 'Instytucja', 'Obniżenie ceny bez uzgodnienia', 'IS zeszła z ceny 6000 na 5000 w PUP Kraków. Precedens blokuje wyższe stawki dla kolejnych wniosków w tym urzędzie.', 'Bartłomiej Olejnik', 'wysoka', NULL);
INSERT INTO zgloszenia (id, data, podmiot_typ, podmiot, typ, powod, opis, autor, waga, klient_id) VALUES ('ZG-003', '2026-04-08', 'klient', 'Zenit sp.j.', 'Klient', 'Brak kontaktu po decyzji', 'Klient nie odbiera od 3 tygodni mimo pozytywnej decyzji. Termin realizacji mija 31.12.', 'Joanna Sadowska', 'niska', NULL);
